import{_ as e,c as n,o as i,a0 as r}from"./chunks/framework.DKRgXLPU.js";const t=JSON.parse('{"title":"Mindfulness in Competition","description":"Apply mindfulness principles during pétanque matches to stay present, manage emotions, and perform at your best when it matters most.","frontmatter":{"title":"Mindfulness in Competition","description":"Apply mindfulness principles during pétanque matches to stay present, manage emotions, and perform at your best when it matters most."},"headers":[],"relativePath":"de/blog/mindfulness-competition.md","filePath":"de/blog/mindfulness-competition.md"}');const a=e({name:"de/blog/mindfulness-competition.md"},[["render",function(e,t,a,s,l,u){return i(),n("div",null,[...t[0]||(t[0]=[r('<h1 id="achtsamkeit-im-wettbewerb" tabindex="-1">Achtsamkeit im Wettbewerb <a class="header-anchor" href="#achtsamkeit-im-wettbewerb" aria-label="Permalink to &quot;Achtsamkeit im Wettbewerb&quot;">​</a></h1><p>Achtsamkeit ist nicht nur etwas für Meditationskissen – sie ist ein entscheidender Wettbewerbsvorteil. Die Fähigkeit, während Wettkämpfen präsent, aufmerksam und besonnen zu bleiben, unterscheidet Spitzensportler von denen, die unter Druck zusammenbrechen.</p><h2 id="was-achtsamkeit-im-wettbewerb-bedeutet" tabindex="-1">Was Achtsamkeit im Wettbewerb bedeutet <a class="header-anchor" href="#was-achtsamkeit-im-wettbewerb-bedeutet" aria-label="Permalink to &quot;Was Achtsamkeit im Wettbewerb bedeutet&quot;">​</a></h2><p>Wettbewerbsorientierte Achtsamkeit ist:</p><ul><li><strong>Achtsamkeit im Hier und Jetzt</strong>: Ganz im Augenblick, nicht in der Vergangenheit oder in Zukunftsängsten versunken.</li><li><strong>Wertfreie Beobachtung</strong>: Wahrnehmen, ohne es als gut oder schlecht zu bewerten.</li><li><strong>Gezielte Aufmerksamkeit</strong>: Die Wahl des Fokuspunktes</li><li><strong>Emotionale Regulation</strong>: Gefühle wahrnehmen, ohne von ihnen kontrolliert zu werden</li></ul><h2 id="das-problem-der-abschweifenden-gedanken" tabindex="-1">Das Problem der abschweifenden Gedanken <a class="header-anchor" href="#das-problem-der-abschweifenden-gedanken" aria-label="Permalink to &quot;Das Problem der abschweifenden Gedanken&quot;">​</a></h2><p>Studien zeigen, dass die Gedanken des Durchschnittsmenschen 47 % der Zeit abschweifen. Im Wettbewerb ist dieses Abschweifen kostspielig:</p><ul><li>Ich denke an den letzten Fehlschuss.</li><li>Sich Sorgen um das Ergebnis machen</li><li>Sich vorstellen, was andere denken</li><li>Feierlichkeiten planen oder Ausreden?</li></ul><p>Jeder Moment, den man mit gedanklichen Zeitreisen verbringt, ist ein Moment, den man nicht mit dem Wurf vor sich verbringt.</p><h2 id="achtsamkeitsfahigkeiten-fur-den-wettbewerb" tabindex="-1">Achtsamkeitsfähigkeiten für den Wettbewerb <a class="header-anchor" href="#achtsamkeitsfahigkeiten-fur-den-wettbewerb" aria-label="Permalink to &quot;Achtsamkeitsfähigkeiten für den Wettbewerb&quot;">​</a></h2><h3 id="_1-verankerung-in-der-gegenwart" tabindex="-1">1. Verankerung in der Gegenwart <a class="header-anchor" href="#_1-verankerung-in-der-gegenwart" aria-label="Permalink to &quot;1. Verankerung in der Gegenwart&quot;">​</a></h3><p>Nutzen Sie sensorische Anker, um in die Gegenwart zurückzukehren:</p><p><strong>Physische Verankerungen:</strong></p><ul><li>Spüre das Gewicht des Balles</li><li>Spüre deine Füße auf dem Boden</li><li>Fühlen Sie die Textur des Griffs</li></ul><p><strong>Umweltanker:</strong></p><ul><li>Betrachten Sie spezifische Details des Geländes.</li><li>Hören Sie Umgebungsgeräusche</li><li>Spüre die Temperatur und den Wind</li></ul><h3 id="_2-beobachten-ohne-zu-reagieren" tabindex="-1">2. Beobachten ohne zu reagieren <a class="header-anchor" href="#_2-beobachten-ohne-zu-reagieren" aria-label="Permalink to &quot;2. Beobachten ohne zu reagieren&quot;">​</a></h3><p>Wenn Emotionen aufkommen (Frustration, Angst, Aufregung), üben Sie Folgendes:</p><ol><li><strong>Hinweis</strong>: „Ich bin frustriert.“</li><li><strong>Name</strong>: &quot;Das ist Frustration&quot;</li><li><strong>Erlauben</strong>: Lass es einfach da sein, ohne dagegen anzukämpfen.</li><li><strong>Zurück</strong>: Lenken Sie Ihre Aufmerksamkeit wieder auf die aktuelle Aufgabe.</li></ol><p>Das Gefühl verschwindet nicht, aber es verliert seine Macht, dich zu kontrollieren.</p><h3 id="_3-fokussierung-auf-einen-einzigen-punkt" tabindex="-1">3. Fokussierung auf einen einzigen Punkt <a class="header-anchor" href="#_3-fokussierung-auf-einen-einzigen-punkt" aria-label="Permalink to &quot;3. Fokussierung auf einen einzigen Punkt&quot;">​</a></h3><p>Übe deine Aufmerksamkeit darauf, dich auf eine Sache zu konzentrieren:</p><p><strong>Vor dem Wurf:</strong></p><ul><li>Konzentriere dich ausschließlich auf das Lesen des Geländes.</li><li>Erst dann, wenn das Ergebnis visualisiert wird</li><li>Dann nur noch abhängig von Ihrer Körperhaltung</li></ul><p><strong>Während des Wurfs:</strong></p><ul><li>Konzentriere dich nur auf das Ziel</li><li>Lass den Körper ohne Einmischung agieren.</li></ul><h3 id="_4-die-denkweise-eines-anfangers" tabindex="-1">4. Die Denkweise eines Anfängers <a class="header-anchor" href="#_4-die-denkweise-eines-anfangers" aria-label="Permalink to &quot;4. Die Denkweise eines Anfängers&quot;">​</a></h3><p>Gehe jeden Wurf so an, als wäre es dein erster:</p><ul><li>Keine Annahmen basierend auf der bisherigen Wertentwicklung</li><li>Ein frischer Blick auf das Gelände</li><li>Neugier statt Erwartung</li></ul><h2 id="praktische-anwendungen" tabindex="-1">Praktische Anwendungen <a class="header-anchor" href="#praktische-anwendungen" aria-label="Permalink to &quot;Praktische Anwendungen&quot;">​</a></h2><h3 id="zwischen-den-wurfen" tabindex="-1">Zwischen den Würfen <a class="header-anchor" href="#zwischen-den-wurfen" aria-label="Permalink to &quot;Zwischen den Würfen&quot;">​</a></h3><p>Die Zeit zwischen den Würfen ist die Zeit, in der die Gedanken am ehesten abschweifen. Nutze diese Zeit bewusst:</p><ul><li><strong>Aktiv beobachten</strong>: Beobachten Sie Ihre Teamkollegen und Gegner mit voller Aufmerksamkeit.</li><li><strong>Bleibe im Einklang mit deinem Körper</strong>: Achte auf deine Atmung, deine Haltung und deinen körperlichen Zustand.</li><li><strong>Mentale Vorbereitung</strong>: Mögliche Szenarien visualisieren</li><li><strong>Aufmerksamkeitspausen</strong>: Gönnen Sie Ihrer Konzentration kurze Pausen.</li></ul><h3 id="wahrend-druckmomenten" tabindex="-1">Während Druckmomenten <a class="header-anchor" href="#wahrend-druckmomenten" aria-label="Permalink to &quot;Während Druckmomenten&quot;">​</a></h3><p>Wenn am meisten auf dem Spiel steht:</p><ol><li><strong>Entschleunigen Sie</strong>: Atmen Sie tief durch.</li><li><strong>Erde dich</strong>: Spüre deine Füße, den Boule-Boden</li><li><strong>Enger Fokus</strong>: Nur dieser Wurf</li><li><strong>Vertrauen</strong>: Loslassen von der Ergebnisorientierung.</li></ol><h3 id="nach-fehlern" tabindex="-1">Nach Fehlern <a class="header-anchor" href="#nach-fehlern" aria-label="Permalink to &quot;Nach Fehlern&quot;">​</a></h3><p>Fehler führen zu Grübeleien. Durchbrechen Sie den Kreislauf:</p><ol><li><strong>Anerkennen</strong>: „Das ist nicht wie geplant verlaufen.“</li><li><strong>Auszug</strong>: „Was kann ich lernen?“</li><li><strong>Veröffentlichung</strong>: „Es ist vorbei, weiter geht’s.“</li><li><strong>Neuausrichtung</strong>: „Was kommt als Nächstes?“</li></ol><h2 id="die-achtsame-vorbereitungsroutine" tabindex="-1">Die achtsame Vorbereitungsroutine <a class="header-anchor" href="#die-achtsame-vorbereitungsroutine" aria-label="Permalink to &quot;Die achtsame Vorbereitungsroutine&quot;">​</a></h2><p>Integrieren Sie Achtsamkeit in Ihren Alltag:</p><ol><li><strong>Ankommen</strong>: Treten Sie mit voller Präsenz in den Kreis ein.</li><li><strong>Atmen</strong>: Ein bewusster Atemzug zur Zentrierung</li><li><strong>Siehe:</strong> Beobachten Sie das Gelände aufmerksam.</li><li><strong>Visualisieren</strong>: Das Ergebnis klar erkennen</li><li><strong>Spüren</strong>: Nimm die Kugel und deinen Körper wahr.</li><li><strong>Loslassen</strong>: Lass los und vertraue.</li></ol><h2 id="haufige-herausforderungen" tabindex="-1">Häufige Herausforderungen <a class="header-anchor" href="#haufige-herausforderungen" aria-label="Permalink to &quot;Häufige Herausforderungen&quot;">​</a></h2><h3 id="quot-ich-kann-nicht-aufhoren-zu-denken-quot" tabindex="-1">&quot;Ich kann nicht aufhören zu denken&quot; <a class="header-anchor" href="#quot-ich-kann-nicht-aufhoren-zu-denken-quot" aria-label="Permalink to &quot;&amp;quot;Ich kann nicht aufhören zu denken&amp;quot;&quot;">​</a></h3><p>Du musst deine Gedanken nicht unterdrücken – folge ihnen einfach nicht. Nimm den Gedanken wahr, lass ihn vorbeiziehen und kehre zu deinem Anker zurück.</p><h3 id="„achtsamkeit-macht-mich-zu-entspannt" tabindex="-1">„Achtsamkeit macht mich zu entspannt.“ <a class="header-anchor" href="#„achtsamkeit-macht-mich-zu-entspannt" aria-label="Permalink to &quot;„Achtsamkeit macht mich zu entspannt.“&quot;">​</a></h3><p>Bei wettbewerbsorientierter Achtsamkeit geht es nicht darum, ruhig zu sein, sondern darum, präsent zu sein. Man kann gleichzeitig wach, energiegeladen und achtsam sein.</p><h3 id="quot-ich-vergesse-achtsam-zu-sein-quot" tabindex="-1">&quot;Ich vergesse, achtsam zu sein.&quot; <a class="header-anchor" href="#quot-ich-vergesse-achtsam-zu-sein-quot" aria-label="Permalink to &quot;&amp;quot;Ich vergesse, achtsam zu sein.&amp;quot;&quot;">​</a></h3><p>Trigger verwenden:</p><ul><li>Das Aufheben der Boule-Kugel = Achtsamkeitsübung</li><li>Das Betreten des Kreises = Erinnerung an die Anwesenheit</li><li>Position beziehen = Aufmerksamkeitsanker</li></ul><h2 id="aufbau-der-fahigkeit" tabindex="-1">Aufbau der Fähigkeit <a class="header-anchor" href="#aufbau-der-fahigkeit" aria-label="Permalink to &quot;Aufbau der Fähigkeit&quot;">​</a></h2><h3 id="tagliche-ubung" tabindex="-1">Tägliche Übung <a class="header-anchor" href="#tagliche-ubung" aria-label="Permalink to &quot;Tägliche Übung&quot;">​</a></h3><p>5-10 Minuten formale Achtsamkeitsübungen bauen die neuronalen Verbindungen auf:</p><ul><li>Atemwahrnehmungsmeditation</li><li>Körperscan-Übung</li><li>Achtsamkeitsübungen</li></ul><h3 id="integration-des-trainings" tabindex="-1">Integration des Trainings <a class="header-anchor" href="#integration-des-trainings" aria-label="Permalink to &quot;Integration des Trainings&quot;">​</a></h3><p>Übe Achtsamkeit während jeder Trainingseinheit:</p><ul><li>Volle Präsenz bei jedem Wurf</li><li>Achten Sie darauf, wann Ihre Aufmerksamkeit abschweift.</li><li>Übung zur Rückkehr zum Fokus</li></ul><h3 id="wettkampfvorbereitung" tabindex="-1">Wettkampfvorbereitung <a class="header-anchor" href="#wettkampfvorbereitung" aria-label="Permalink to &quot;Wettkampfvorbereitung&quot;">​</a></h3><p>Vor den Spielen:</p><ul><li>Kurze Achtsamkeitsübung</li><li>Setzen Sie sich eine Absicht für den Fokus auf die Gegenwart</li><li>Erinnere dich an deine Ankerpunkte</li></ul><h2 id="der-wettbewerbsvorteil" tabindex="-1">Der Wettbewerbsvorteil <a class="header-anchor" href="#der-wettbewerbsvorteil" aria-label="Permalink to &quot;Der Wettbewerbsvorteil&quot;">​</a></h2><p>Bewusste Wettbewerber haben Vorteile:</p><ul><li><strong>Schnellere Fehlerbehebung</strong></li><li><strong>Bessere Entscheidungsfindung</strong> unter Druck</li><li><strong>Konstantere</strong> Leistung</li><li><strong>Mehr Freude</strong> am Wettbewerb</li><li><strong>Reduziertes Burnout</strong> und weniger Angstzustände</li></ul><p>Der Spieler, der bei jedem Wurf voll konzentriert ist, während die anderen in Gedanken versunken sind, hat einen deutlichen Vorteil.</p><hr><p>| <em>Verwandtes Thema: <a href="/en/education/mindfulness/">Einführung in die Achtsamkeit</a> | <a href="/en/education/mindfulness/techniques">Achtsamkeitstechniken</a> | <a href="/en/education/mindfulness/daily-practice">Tägliche Übung</a></em> |</p>',66)])])}]]);export{t as __pageData,a as default};
